 "content": "from collections import Counter


def transform(grid):
    """Fill rectangular hollow frames, using parity to choose the fill color."""
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w:
        return [row[:] for row in grid]

    # The surrounding field is the most frequent color in these diagrams.
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # A frame is a solid, single-color rectangular perimeter around a
    # background-only interior. Odd interior side length(s) map to 7;
    # even-by-even interiors map to 2.
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    color = grid[top][left]
                    if color == background:
                        continue
                    if any(grid[top][c] != color or grid[bottom][c] != color
                           for c in range(left, right + 1)):
                        continue
                    if any(grid[r][left] != color or grid[r][right] != color
                           for r in range(top, bottom + 1)):
                        continue
                    if any(grid[r][c] != background
                           for r in range(top + 1, bottom)
                           for c in range(left + 1, right)):
                        continue
                    ih, iw = bottom - top - 1, right - left - 1
                    fill = 7 if (ih % 2 or iw % 2) else 2
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            out[r][c] = fill
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
